import {it,expect,vi} from 'vitest'
import {LoopSession} from './loop-session'
import {LoopGraph} from './loop-graph'
import {AudioBufferPool} from '../../listen-upstream/realtime/cache'
const param=()=>({value:.76,setValueAtTime:vi.fn(),linearRampToValueAtTime:vi.fn(),cancelScheduledValues:vi.fn()})
const node=()=>({gain:param(),connect:vi.fn(),disconnect:vi.fn(),start:vi.fn(),stop:vi.fn(),loop:false,loopEnd:0,buffer:null})
function setup(){const lengthFrames=432000,startFrame=1764000,track:any={id:'a',duration:100,native:{url:'a',sha256:'sha',duration:100}},buffer:any={length:lengthFrames+353,duration:(lengthFrames+353)/44100},approval:any={id:'loop',nativeGain:.76,fadeSeconds:.008,startFrame,lengthFrames},ready:any={approval,track,buffer,bodyBuffers:new Map([['a',buffer]]),release:vi.fn()},stream:any={deadline:60,pins:new Set(['a']),pump:vi.fn(),dispose:vi.fn()},source:any={track,gain:{gain:param()},stream,sources:[]},ctx:any={currentTime:10,createGain:node,createBufferSource:node,sampleRate:44100},host:any={ctx,cache:{pool:new AudioBufferPool()},active:source,position:10,playing:true,busy:false,gate:{locked:false},monitor:node(),log:vi.fn(),graph:vi.fn((track,at,offset)=>({track,at,offset,gain:{gain:param()},stream:{pump:vi.fn(),pins:new Set()},sources:[]})),nativeSource:vi.fn(),retire:vi.fn(),protected:vi.fn()},catalog:any={candidates:vi.fn(async()=>[{startFrame}]),prepare:vi.fn(async()=>ready),dispose:vi.fn()},session=new LoopSession(host,new URL('https://example.test'),vi.fn(),catalog);return{host,ctx,ready,source,session,catalog,stream}}
it('holds more than original source duration with a short loop and returns from its approved end phase',async()=>{const f=setup();f.session.configure(true,16);await f.session.warm();expect(f.session.arm()).toBe(true);expect(f.session.pending!.end-f.session.pending!.start).toBeCloseTo(156.73469);f.ctx.currentTime=170;f.session.tick();expect(f.session.position).toBeLessThan(50);expect(f.host.active).toBe(f.source);expect(f.source.stream.deadline).toBe(Infinity);const end=f.session.pending!.end;f.ctx.currentTime=end+.009;f.session.tick();expect(f.host.active.track.id).toBe('a');expect(f.host.active.offset).toBeCloseTo(49.795918);expect(f.session.revision).toBe(1);expect(f.ready.release).not.toHaveBeenCalled();f.ctx.currentTime=end+.021;f.session.tick();expect(f.ready.release).toHaveBeenCalledTimes(1)})
it('early next restores the half-loop source phase and holds its music clock during pause',async()=>{const f=setup();f.session.configure(true,4);await f.session.warm();f.session.arm();f.ctx.currentTime=41;const position=f.session.position;expect(f.session.position).toBe(position);expect(f.session.release()).toBe(true);expect(f.session.pending!.plan.entry).toBeCloseTo(44.897959);expect(f.session.pending!.end).toBeCloseTo(44.897959);f.ctx.currentTime=44.91;f.session.tick();expect(f.host.active.offset).toBeCloseTo(44.897959);expect(f.host.log).toHaveBeenCalledWith('loop_extension_complete',expect.objectContaining({cycles:.5}))})
it('never masks a pre-entry gap and cancellation restores A without committing',async()=>{const f=setup();f.stream.deadline=39;f.session.configure(true);await f.session.warm();f.session.arm();expect(f.source.stream.deadline).toBe(39);expect(f.session.cancel()).toBe(true);expect(f.host.active).toBe(f.source);expect(f.source.stream).toBe(f.stream);expect(f.ready.release).toHaveBeenCalled();expect(f.session.revision).toBe(0)})
it('stop and source changes release ownership; a stale warm cannot install',async()=>{const f=setup();f.session.configure(true);await f.session.warm();f.session.arm();f.session.stop();f.ctx.currentTime=200;f.session.tick();expect(f.session.pending).toBeNull();expect(f.session.revision).toBe(0);let done!:(x:any)=>void;f.catalog.prepare.mockImplementation(()=>new Promise(r=>done=r));const task=f.session.warm();await vi.waitFor(()=>expect(done).toBeTypeOf('function'));f.host.active={...f.source};done(f.ready);await task;expect(f.session.upcoming).toBeNull();expect(f.ready.release).toHaveBeenCalledTimes(2)})
it('graph retains only one looping source regardless of cycles and never schedules an arbitrary exit',()=>{const f=setup(),original=param(),nodes:any[]=[];f.ctx.createBufferSource=()=>{const n=node();nodes.push(n);return n};const g=new LoopGraph(f.ctx,node() as any,f.ready,original as any,20,16);expect(nodes).toHaveLength(1);expect(nodes[0].loopEnd).toBeCloseTo(432000/44100);expect(()=>g.setExit({atFrame:100,sourceFrame:1764100})).toThrow();g.cancel();expect(original.setValueAtTime).toHaveBeenLastCalledWith(.76,10)})

it('shortening an armed future loop preserves its measured entry automation',()=>{const f=setup(),nodes:any[]=[];f.ctx.createGain=()=>{const n=node();nodes.push(n);return n};const g=new LoopGraph(f.ctx,node() as any,f.ready,param() as any,20,4);g.setExit(g.nextExit(4)!);const p=nodes[0].gain;expect(p.setValueAtTime).toHaveBeenCalledWith(0,20);expect(p.linearRampToValueAtTime).toHaveBeenCalledWith(.76,20.008);expect(p.cancelScheduledValues.mock.calls.every(([t]:number[])=>t>20.008)).toBe(true)})

it('transient preparation failure can retry after explicit re-enable without replaying completed loops',async()=>{const f=setup();f.catalog.prepare.mockRejectedValueOnce(Error('temporary network'));f.session.configure(true);await f.session.warm();expect(f.session.snapshot().state).toBe('unavailable');f.session.configure(false);f.session.configure(true);await f.session.warm();expect(f.session.upcoming).toBe(f.ready);expect(f.catalog.prepare).toHaveBeenCalledTimes(2)})
